 1	import { Router, type IRouter, type Request } from "express";
 2	import { and, eq, desc, asc } from "drizzle-orm";
 3	import {
 4	  db,
 5	  comments,
 6	  activityFeed,
 7	  projectVersions,
 8	  appUsers,
 9	} from "@workspace/db";
10	
11	const router: IRouter = Router();
12	
13	// `req.appUserId` is populated by the `requireAuth` middleware mounted
14	// upstream in `routes/index.ts`. The project-scoped routes below also pass
15	// through `requireProjectAccess`, so we do not re-verify access here.
16	function currentUserId(req: Request): number | null {
17	  return typeof req.appUserId === "number" ? req.appUserId : null;
18	}
19	
20	type AuthorInfo = {
21	  id: number;
22	  firstName: string | null;
23	  lastName: string | null;
24	  imageUrl: string | null;
25	  email: string | null;
26	} | null;
27	
28	async function getUsersById(userIds: number[]): Promise<Map<number, AuthorInfo>> {
29	  const map = new Map<number, AuthorInfo>();
30	  if (userIds.length === 0) return map;
31	  const unique = [...new Set(userIds)];
32	  const rows = await db.select().from(appUsers);
33	  const byId = new Map(rows.map((r) => [r.id, r]));
34	  for (const id of unique) {
35	    const u = byId.get(id);
36	    map.set(
37	      id,
38	      u
39	        ? {
40	            id: u.id,
41	            firstName: u.firstName,
42	            lastName: u.lastName,
43	            imageUrl: u.imageUrl,
44	            email: u.email,
45	          }
46	        : null,
47	    );
48	  }
49	  return map;
50	}
51	
52	function paramAsString(v: unknown): string {
53	  if (typeof v === "string") return v;
54	  if (Array.isArray(v) && typeof v[0] === "string") return v[0];
55	  return "";
56	}
57	
58	function parseProjectId(req: Request): number {
59	  return parseInt(paramAsString(req.params.projectId) || "0", 10);
60	}

