      });
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      res.status(502).json({ error: `AI generation failed: ${msg}` });
      return;
    }

    const parsed = tryParseJsonObject<{
      name?: string;
      description?: string;
      gameType?: string;
      genre?: string;
      playerCount?: string;
      targetDuration?: string;
      complexityScore?: number;
      blueprint?: string;
