139	function ClerkQueryClientCacheInvalidator() {
140	  const { addListener } = useClerk();
141	  const qc = useQueryClient();
142	  const prevUserIdRef = useRef<string | null | undefined>(undefined);
143	
144	  useEffect(() => {
145	    const unsubscribe = addListener(({ user }) => {
146	      const userId = user?.id ?? null;
147	      if (
148	        prevUserIdRef.current !== undefined &&
149	        prevUserIdRef.current !== userId
150	      ) {
151	        qc.clear();
152	      }
153	      prevUserIdRef.current = userId;
154	    });
155	    return unsubscribe;
156	  }, [addListener, qc]);
157	
158	  return null;
159	}
