111	export type WorkspaceProviderName = "anthropic" | "openai" | "gemini" | "openrouter";
112	
113	export interface WorkspaceProviderSetting {
114	  provider: WorkspaceProviderName;
115	  enabled: boolean;
116	  hasKey: boolean;
117	}

